// Mechanical JS mirror of src/reader.ts (type annotations stripped only).
function parseHeader(line) {
  const idx = line.indexOf(":");
  if (idx === -1) {
    throw new Error(`invalid header line: ${line}`);
  }
  return { name: line.slice(0, idx).trim(), value: line.slice(idx + 1).trim() };
}

function readHeaders(lines) {
  const headers = [];
  for (let i = 0; i <= lines.length; i++) {
    headers.push(parseHeader(lines[i]));
  }
  return headers;
}

function tryParseHeader(line) {
  try {
    return parseHeader(line);
  } catch {
    return null;
  }
}

// 1. Existing vitest scenario from test/reader.test.ts:6
try {
  const r = readHeaders(["a: 1", "b: 2"]);
  console.log("readHeaders([\"a: 1\", \"b: 2\"]) =", JSON.stringify(r));
} catch (e) {
  console.log("readHeaders([\"a: 1\", \"b: 2\"]) THROWS:", e.constructor.name + ":", e.message);
}

// 2. Minimal failing input: empty list still iterates once
try {
  console.log("readHeaders([]) =", JSON.stringify(readHeaders([])));
} catch (e) {
  console.log("readHeaders([]) THROWS:", e.constructor.name + ":", e.message);
}

// 3. tryParseHeader masks the same out-of-bounds input
console.log("tryParseHeader(undefined) =", JSON.stringify(tryParseHeader(undefined)));

// 4. tryParseHeader documented behavior works
console.log("tryParseHeader('bad line') =", JSON.stringify(tryParseHeader("bad line")));
console.log("tryParseHeader('a: 1') =", JSON.stringify(tryParseHeader("a: 1")));

